package au.com.rootcauseobd.fleet.data

/**
 * Pinned cloud signing keys (generated by scripts/export_cloud_keys.py --kotlin-out).
 *
 * Same rule as the edge daemon's `cloud_keys.rs`: empty on purpose. With no
 * pinned key no lease verifies, so release builds run on the free Community
 * plan until a production public key is pinned. Debug builds may also trust
 * the keys the configured server publishes at /api/v1/auth/jwks (see
 * [CloudAccount]), so local development works without pinning.
 *
 * Only ever the public half of a production key. No private key is in this repository.
 */
object CloudKeys {
    /** kid → 64-hex Ed25519 public key, newest first. */
    val PINNED: Map<String, String> = linkedMapOf()

    fun pinned(): Map<String, ByteArray> = PINNED.mapValues { (_, hex) -> LicenceVerifier.hexKey(hex) }
}
